/* selectSurvshtListTotalCount - kim.seong.gyu */

SELECT
    COUNT(*) AS CNT
FROM SBB100  /* 설문지 */
WHERE 1=1



    AND QUSTNB_NM LIKE '%' || #{QUSTNB_NM} || '%'




    AND SRVY_BGNG_YMD <= #{SERCH_YMN}
    AND SRVY_END_YMD >= #{SERCH_YMN}




    AND SRVY_BGNG_YMD              >=      TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS')
    AND SRVY_END_YMD              <=       TO_DATE(#{END_DATE} || '000000', 'YYYYMMDDHH24MISS')+1




        AND UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}

/* selectSurvshtList - kim.seong.gyu */
SELECT A.QUSTNB_MNG_NO, A.QUSTNB_TMPT_MNG_NO, A.UNT_TASKWK_SE_CD AS TASKWK_SYS_SE_CD, A.QUSTNB_NM, A.SRVY_PURPS_CN, A.SRVY_WRT_GUIDAN_CN, A.SRVY_BGNG_YMD, A.SRVY_END_YMD, A.SRVY_TRGT_SE_CD, A.SRVY_PRGRS_STTS_SE_CD, (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'SRVY_PRGRS_STTS_SE_CD' AND D.CMMNS_CD_VALUE = A.SRVY_PRGRS_STTS_SE_CD ) AS SRVY_PRGRS_STTS_SE_NM, A.FRST_RGTR_ID, TO_CHAR(A.FRST_REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FRST_REG_DT, A.LAST_MDFR_ID, TO_CHAR(A.LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI:SS') AS LAST_MDFCN_DT FROM SBB100 A /* 설문지 */ WHERE 1=1
AND A.QUSTNB_NM LIKE '%' || #{QUSTNB_NM} || '%'
AND A.SRVY_BGNG_YMD <= #{SERCH_YMN} AND A.SRVY_END_YMD >= #{SERCH_YMN}
AND A.SRVY_BGNG_YMD >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS') AND A.SRVY_END_YMD <= TO_DATE(#{END_DATE} || '000000', 'YYYYMMDDHH24MISS')+1
AND UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
ORDER BY A.FRST_REG_DT DESC

