/* selectSurvshtTmptListTotalCount - Song.Tae.soo */

SELECT
    COUNT(*) AS CNT
FROM SBB000  /* 설문지 */
WHERE 1=1




           AND (QUSTNB_TMPT_MNG_NO = #{SEARCH_DATA} OR QUSTNB_TMPT_NM LIKE '%'||#{SEARCH_DATA}||'%' OR QUSTNB_NM LIKE '%'||#{SEARCH_DATA}||'%')






           AND QUSTNB_TMPT_MNG_NO = #{SEARCH_DATA}






           AND QUSTNB_TMPT_NM LIKE '%' || #{SEARCH_DATA} || '%'






           AND QUSTNB_NM LIKE '%' || #{SEARCH_DATA} || '%'





    AND SRVY_BGNG_YMD              >=      TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS')
    AND SRVY_END_YMD              <       TO_DATE(#{END_DATE} || '000000', 'YYYYMMDDHH24MISS')+1




        AND UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}




        AND USE_YN = #{USE_YN}

/* selectSurvshtTmptList - Song.Tae.soo */
SELECT A.QUSTNB_TMPT_MNG_NO, A.UNT_TASKWK_SE_CD AS TASKWK_SYS_SE_CD, A.QUSTNB_TMPT_NM, A.QUSTNB_NM, A.SRVY_PURPS_CN, A.SRVY_WRT_GUIDAN_CN, A.SRVY_BGNG_YMD, A.SRVY_END_YMD, A.SRVY_TRGT_SE_CD, A.USE_YN, (CASE A.USE_YN WHEN 'Y' THEN '사용' ELSE '사용 안함' END) AS USE_YN_NM, A.SRVY_PRGRS_STTS_SE_CD, (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'SRVY_PRGRS_STTS_SE_CD' AND D.CMMNS_CD_VALUE = A.SRVY_PRGRS_STTS_SE_CD ) AS SRVY_PRGRS_STTS_SE_NM, A.FRST_RGTR_ID, TO_CHAR(A.FRST_REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FRST_REG_DT, A.LAST_MDFR_ID, TO_CHAR(A.LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI:SS') AS LAST_MDFCN_DT FROM SBB000 A /* 설문지 */ WHERE 1=1
AND (A.QUSTNB_TMPT_MNG_NO = #{SEARCH_DATA} OR A.QUSTNB_TMPT_NM LIKE '%'||#{SEARCH_DATA}||'%' OR A.QUSTNB_NM LIKE '%'||#{SEARCH_DATA}||'%')
AND A.QUSTNB_TMPT_MNG_NO = #{SEARCH_DATA}
AND A.QUSTNB_TMPT_NM LIKE '%' || #{SEARCH_DATA} || '%'
AND A.QUSTNB_NM LIKE '%' || #{SEARCH_DATA} || '%'
AND A.SRVY_BGNG_YMD <= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS') AND A.SRVY_END_YMD > TO_DATE(#{END_DATE} || '000000', 'YYYYMMDDHH24MISS')+1
AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND A.USE_YN = #{USE_YN}
ORDER BY A.FRST_REG_DT DESC

