/* selectSurvshtTmptRelmMarkList */ SELECT A.QUSTNB_TMPT_MNG_NO , A.UNT_TASKWK_SE_CD , A.QUSTNB_TMPT_NM , A.QUSTNB_NM , A.SRVY_PURPS_CN , A.SRVY_WRT_GUIDAN_CN , A.SRVY_BGNG_YMD , A.SRVY_END_YMD , A.USE_YN , (CASE A.USE_YN WHEN 'Y' THEN '사용' ELSE '미사용' END) AS USE_YN_NM , A.SRVY_TRGT_SE_CD , A.SRVY_PRGRS_STTS_SE_CD , A.WRTR_ID , C##RG.DEC_B64(A.WRTR_NM_ENCPT) AS WRTR_NM_ENCPT , A.FRST_RGTR_ID , A.FRST_REG_DT , A.LAST_MDFR_ID , A.LAST_MDFCN_DT FROM SBB000 A
WHERE A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND A.QUSTNB_TMPT_NM LIKE '%' || #{QUSTNB_TMPT_NM} || '%'
AND A.SRVY_BGNG_YMD >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS') AND A.SRVY_END_YMD <= TO_DATE(#{END_DATE} || '000000', 'YYYYMMDDHH24MISS')+1
ORDER BY FRST_REG_DT DESC

