 MERGE INTO SBB220 /* 항목별응답내용 */
 USING DUAL
    ON (QESITM_MNG_NO = #{QESITM_MNG_NO}
   AND  SRVY_RSPNS_MNG_NO = #{SRVY_RSPNS_MNG_NO})
  WHEN MATCHED THEN
UPDATE SET
       QESITM_SINGL_RSPNS_VALUE = #{QESITM_SINGL_RSPNS_VALUE},   /* 문항단일응답값 */
       QESITM_COMPNO_RSPNS_VALUE = #{QESITM_COMPNO_RSPNS_VALUE}, /* 문항복수응답값 */
       QESITM_RSPNS_CN = #{QESITM_RSPNS_CN},                     /* 문항응답내용 */
       LAST_MDFR_ID = #{USER_ID},                                /* 수정아이디 */
       LAST_MDFCN_DT = SYSDATE                                   /* 수정일시 */
  WHEN NOT MATCHED THEN
 INSERT (
     QESITM_MNG_NO
     , SRVY_RSPNS_MNG_NO
     , QESITM_SINGL_RSPNS_VALUE
     , QESITM_COMPNO_RSPNS_VALUE
     , QESITM_RSPNS_CN
     , FRST_RGTR_ID
     , FRST_REG_DT
     , LAST_MDFR_ID
     , LAST_MDFCN_DT
 ) VALUES (
     #{QESITM_MNG_NO}
     , #{SRVY_RSPNS_MNG_NO}
     , #{QESITM_SINGL_RSPNS_VALUE}
     , #{QESITM_COMPNO_RSPNS_VALUE}
     , #{QESITM_RSPNS_CN}
     , #{USER_ID}
     , SYSDATE
     , #{USER_ID}
     , SYSDATE
 )

        UPDATE SBB100 SET
			SRVY_PRGRS_STTS_SE_CD = #{SRVY_PRGRS_STTS_SE_CD},
